using System;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;
internal static class NativeTheme {
 internal static Action<Window> ReviewShown {get;set;}
 static Brush Brush(string hex)=>new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex));
 internal static Window Dialog(Window owner,string title,bool dark){
  bool hc=SystemParameters.HighContrast;
  var window=new Window{Owner=owner,Title=title,Width=Math.Min(510,SystemParameters.WorkArea.Width),MaxHeight=Math.Max(200,SystemParameters.WorkArea.Height-32),SizeToContent=SizeToContent.Height,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,FontFamily=new FontFamily("Segoe UI"),FontSize=13,Background=hc?SystemColors.WindowBrush:Brush(dark?"#17263c":"#f3f6fb"),Foreground=hc?SystemColors.WindowTextBrush:Brush(dark?"#edf3fc":"#17263c")};
  window.Resources["Surface"]=hc?SystemColors.ControlBrush:Brush(dark?"#213249":"#ffffff");window.Resources["Line"]=hc?SystemColors.WindowTextBrush:Brush(dark?"#8294ad":"#73859e");window.Resources["Accent"]=hc?SystemColors.HighlightBrush:Brush(dark?"#8eb8ff":"#2360d3");window.Resources["AccentText"]=hc?SystemColors.HighlightTextBrush:Brush(dark?"#17263c":"#ffffff");
  window.Resources[typeof(Button)]=(Style)XamlReader.Parse("<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' TargetType='Button'><Setter Property='MinHeight' Value='36'/><Setter Property='Padding' Value='12,6'/><Setter Property='Foreground' Value='{Binding Foreground, RelativeSource={RelativeSource AncestorType=Window}}'/><Setter Property='Background' Value='{DynamicResource Surface}'/><Setter Property='BorderBrush' Value='{DynamicResource Line}'/><Setter Property='BorderThickness' Value='1'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='Button'><Border x:Name='edge' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='{TemplateBinding BorderThickness}' CornerRadius='10' Padding='{TemplateBinding Padding}'><ContentPresenter HorizontalAlignment='Center' VerticalAlignment='Center'/></Border><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='edge' Property='BorderBrush' Value='{DynamicResource Accent}'/></Trigger><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='edge' Property='BorderBrush' Value='{DynamicResource Accent}'/><Setter TargetName='edge' Property='BorderThickness' Value='2'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>");
  window.Loaded+=(_,__)=>ReviewShown?.Invoke(window);return window;
 }
 internal static StackPanel Body()=>new StackPanel{Margin=new Thickness(2)};
 internal static TextBlock Label(string text)=>new TextBlock{Text=text,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,16)};
 internal static StackPanel Row()=>new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};
 internal static void Layout(Window window,StackPanel body,StackPanel row){var grid=new Grid{Margin=new Thickness(24)};grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});var scroll=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,Margin=new Thickness(0,0,0,20)};grid.Children.Add(scroll);Grid.SetRow(row,1);grid.Children.Add(row);window.Content=grid;}
 internal static Button Cancel(Window window,string text="Cancel"){var button=new Button{Content=text,IsCancel=true,IsDefault=true};button.Click+=(_,__)=>window.DialogResult=false;return button;}
 internal static Button Primary(Window window,string text){var button=new Button{Content=text,Margin=new Thickness(12,0,0,0)};button.SetResourceReference(Control.BackgroundProperty,"Accent");button.SetResourceReference(Control.ForegroundProperty,"AccentText");button.Click+=(_,__)=>window.DialogResult=true;return button;}
 internal static Border Input(Window window,Control control){control.Background=Brushes.Transparent;control.Foreground=window.Foreground;control.BorderThickness=new Thickness(0);control.Padding=new Thickness(12);control.FontSize=16;control.MinHeight=44;var border=new Border{CornerRadius=new CornerRadius(10),BorderThickness=new Thickness(1),Child=control};border.SetResourceReference(Border.BackgroundProperty,"Surface");border.SetResourceReference(Border.BorderBrushProperty,"Line");control.IsKeyboardFocusWithinChanged+=(_,__)=>{border.SetResourceReference(Border.BorderBrushProperty,control.IsKeyboardFocusWithin?"Accent":"Line");border.BorderThickness=new Thickness(control.IsKeyboardFocusWithin?2:1);};return border;}
}
